import numpy as np
def comps(g,c):
    h,w=len(g),len(g[0]); seen=set(); res=[]
    for y in range(h):
        for x in range(w):
            if g[y][x]==c and (y,x) not in seen:
                stack=[(y,x)]; seen.add((y,x)); sz=0
                while stack:
                    a,b=stack.pop(); sz+=1
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        p,q=a+dy,b+dx
                        if 0<=p<h and 0<=q<w and g[p][q]==c and (p,q) not in seen:
                            seen.add((p,q)); stack.append((p,q))
                res.append(sz)
    return sorted(res,reverse=True)
